insert into public.wired_question_banks (version, set_kind, bank, active, approved_at)
values ('k2-v1', 'k2', $bank${"version":"k2-v1","set_kind":"k2","approved_at":"2026-11-18","source":"Wired_Quiz_K2_Question_Set.md","weights":{"scenario":0.5,"frequency":0.5},"instructions":"Think about your child over the past month. For each moment, pick the ONE answer that sounds most like your child right now, even if more than one fits. There are no wrong answers: every choice is a strength.","frequency_stem":"In the past month, how often does your child...","scale":{"points":5,"labels":["Rarely","Sometimes","Often","Very often","Constantly"]},"scenarios":[{"id":"k2-s01","prompt":"A rainy afternoon with nothing planned. Your child is most likely to...","options":[{"id":"k2-s01-a","domain":"storyteller","text":"make up a story, or ask you to read one"},{"id":"k2-s01-b","domain":"organizer","text":"sort, count, or set up a game with rules"},{"id":"k2-s01-c","domain":"designer","text":"draw, or build something tall with blocks"}]},{"id":"k2-s02","prompt":"At the park, your child is most likely to...","options":[{"id":"k2-s02-a","domain":"maker","text":"climb, run, or dig in the sand"},{"id":"k2-s02-b","domain":"psalmist","text":"sing, or make up a chant while they swing"},{"id":"k2-s02-c","domain":"connector","text":"find the other kids and start a game"}]},{"id":"k2-s03","prompt":"On a slow evening walk, your child is most likely to...","options":[{"id":"k2-s03-a","domain":"ponderer","text":"walk along quietly, lost in their own thoughts"},{"id":"k2-s03-b","domain":"cultivator","text":"stop to look at bugs, leaves or birds"},{"id":"k2-s03-c","domain":"seeker","text":"ask a big question, like where heaven is"}]},{"id":"k2-s04","prompt":"After you read a story together, your child...","options":[{"id":"k2-s04-a","domain":"storyteller","text":"tells it back, or makes up a new ending"},{"id":"k2-s04-b","domain":"maker","text":"acts it out, or builds something from it"},{"id":"k2-s04-c","domain":"ponderer","text":"goes quiet, then brings it up days later"}]},{"id":"k2-s05","prompt":"On a car ride, your child is most likely to...","options":[{"id":"k2-s05-a","domain":"organizer","text":"count trucks, read signs, or keep track of the turns"},{"id":"k2-s05-b","domain":"psalmist","text":"sing along or tap out a beat"},{"id":"k2-s05-c","domain":"cultivator","text":"watch for cows, horses or birds out the window"}]},{"id":"k2-s06","prompt":"At church or Sunday school, your child loves...","options":[{"id":"k2-s06-a","domain":"designer","text":"the coloring page or the craft"},{"id":"k2-s06-b","domain":"connector","text":"seeing friends and talking with everyone"},{"id":"k2-s06-c","domain":"seeker","text":"asking questions about God and the Bible story"}]},{"id":"k2-s07","prompt":"At bedtime, your child wants to...","options":[{"id":"k2-s07-a","domain":"storyteller","text":"hear one more story, or tell you all about their day"},{"id":"k2-s07-b","domain":"psalmist","text":"sing a song, or have you sing one"},{"id":"k2-s07-c","domain":"seeker","text":"pray, and ask you big questions about God"}]},{"id":"k2-s08","prompt":"With a new game or puzzle, your child...","options":[{"id":"k2-s08-a","domain":"organizer","text":"wants to know every rule and how to win"},{"id":"k2-s08-b","domain":"connector","text":"wants the whole family to play"},{"id":"k2-s08-c","domain":"ponderer","text":"likes to work on it alone, at their own pace"}]},{"id":"k2-s09","prompt":"Give your child a big empty box and they turn it into...","options":[{"id":"k2-s09-a","domain":"designer","text":"a house or a rocket they plan and decorate"},{"id":"k2-s09-b","domain":"maker","text":"a fort to climb into, or a car to push around"},{"id":"k2-s09-c","domain":"cultivator","text":"a home for a pet, or for the bugs they found"}]},{"id":"k2-s10","prompt":"When family or friends come over, your child...","options":[{"id":"k2-s10-a","domain":"storyteller","text":"tells them everything, with lots of details"},{"id":"k2-s10-b","domain":"connector","text":"plays host and makes sure everyone is included"},{"id":"k2-s10-c","domain":"cultivator","text":"wants to show them the garden, the pets or a bug jar"}]},{"id":"k2-s11","prompt":"Helping you in the kitchen, your child loves to...","options":[{"id":"k2-s11-a","domain":"organizer","text":"measure, count and do the steps in order"},{"id":"k2-s11-b","domain":"maker","text":"stir, pour, knead and get their hands in it"},{"id":"k2-s11-c","domain":"seeker","text":"talk with you about big things, like why God made us"}]},{"id":"k2-s12","prompt":"Playing alone in their room, your child is most likely to...","options":[{"id":"k2-s12-a","domain":"designer","text":"draw, build, or arrange things just so"},{"id":"k2-s12-b","domain":"psalmist","text":"sing, dance or play music"},{"id":"k2-s12-c","domain":"ponderer","text":"daydream, look at books, or simply think"}]}],"frequency":[{"id":"k2-f01","domain":"storyteller","text":"play with words: new words, rhymes or long stories"},{"id":"k2-f02","domain":"organizer","text":"count, sort, or ask how something works"},{"id":"k2-f03","domain":"designer","text":"draw, build, or notice shapes and where things go"},{"id":"k2-f04","domain":"maker","text":"want to touch, move or make things with their hands"},{"id":"k2-f05","domain":"psalmist","text":"sing, hum or keep a beat"},{"id":"k2-f06","domain":"connector","text":"notice how others feel and want to play together"},{"id":"k2-f07","domain":"ponderer","text":"want quiet time to play or think on their own"},{"id":"k2-f08","domain":"cultivator","text":"notice or ask about plants, animals or the weather"},{"id":"k2-f09","domain":"seeker","text":"ask big questions about God, heaven, or right and wrong"}]}$bank$::jsonb, true, '2026-11-18T12:00:00Z')
on conflict (version) do nothing;

insert into public.wired_question_banks (version, set_kind, bank, active, approved_at)
values ('g35-v1', 'g3_5', $bank${"version":"g35-v1","set_kind":"g3_5","approved_at":"2026-11-18","source":"Wired_Quiz_Grades3-5_Question_Set.md","weights":{"scenario":0.5,"frequency":0.5},"instructions":"Think about your child over the past month. For each moment, pick the ONE answer that sounds most like your child right now, even if more than one fits. There are no wrong answers: every choice is a strength.","frequency_stem":"In the past month, how often does your child...","scale":{"points":5,"labels":["Rarely","Sometimes","Often","Very often","Constantly"]},"scenarios":[{"id":"g35-s01","prompt":"A free afternoon with no plans. Your child is most likely to...","options":[{"id":"g35-s01-a","domain":"storyteller","text":"curl up with a book, or write a story or comic"},{"id":"g35-s01-b","domain":"organizer","text":"work on a puzzle, a code, or a game with lots of rules"},{"id":"g35-s01-c","domain":"designer","text":"draw, design a Lego build, or rearrange their room"}]},{"id":"g35-s02","prompt":"At co-op or a group class, your child lights up during...","options":[{"id":"g35-s02-a","domain":"maker","text":"anything hands-on: experiments, crafts, games that move"},{"id":"g35-s02-b","domain":"psalmist","text":"music time, singing, or anything with a rhythm"},{"id":"g35-s02-c","domain":"connector","text":"group work, and getting to know the other kids"}]},{"id":"g35-s03","prompt":"On a hike or a walk in the woods, your child...","options":[{"id":"g35-s03-a","domain":"ponderer","text":"goes quiet and seems to enjoy their own thoughts"},{"id":"g35-s03-b","domain":"cultivator","text":"spots tracks, birds or plants and wants to know what they are"},{"id":"g35-s03-c","domain":"seeker","text":"asks big questions, like why God made the world this way"}]},{"id":"g35-s04","prompt":"When something exciting happens, your child wants to...","options":[{"id":"g35-s04-a","domain":"storyteller","text":"tell you every detail, start to finish"},{"id":"g35-s04-b","domain":"maker","text":"show you, act it out, or rebuild it"},{"id":"g35-s04-c","domain":"ponderer","text":"think it over first and talk about it later"}]},{"id":"g35-s05","prompt":"On a long car trip, your child passes the time by...","options":[{"id":"g35-s05-a","domain":"organizer","text":"tracking the miles, the map, or the time left"},{"id":"g35-s05-b","domain":"psalmist","text":"listening to music, singing, or making up songs"},{"id":"g35-s05-c","domain":"cultivator","text":"watching for animals, farms and changes in the land"}]},{"id":"g35-s06","prompt":"At church, your child is most drawn to...","options":[{"id":"g35-s06-a","domain":"designer","text":"the art and the building, or drawing what they hear"},{"id":"g35-s06-b","domain":"connector","text":"the people: friends, older folks, the greeters"},{"id":"g35-s06-c","domain":"seeker","text":"the Bible lesson, and asking questions about it later"}]},{"id":"g35-s07","prompt":"At the end of the day, your child is most likely to...","options":[{"id":"g35-s07-a","domain":"storyteller","text":"read late, or tell you a long story from their day"},{"id":"g35-s07-b","domain":"psalmist","text":"listen to music, hum, or sing to themselves"},{"id":"g35-s07-c","domain":"seeker","text":"ask about God, heaven, or what is right and wrong"}]},{"id":"g35-s08","prompt":"On family game night, your child...","options":[{"id":"g35-s08-a","domain":"organizer","text":"wants to master the strategy and keep score"},{"id":"g35-s08-b","domain":"connector","text":"cares most that everyone is having fun together"},{"id":"g35-s08-c","domain":"ponderer","text":"enjoys it, then wants some quiet time alone afterward"}]},{"id":"g35-s09","prompt":"Given a free Saturday and some supplies, your child would...","options":[{"id":"g35-s09-a","domain":"designer","text":"sketch a plan and build something that looks just right"},{"id":"g35-s09-b","domain":"maker","text":"build, take apart or fix something with real tools"},{"id":"g35-s09-c","domain":"cultivator","text":"plant something, care for a pet, or set up a bug habitat"}]},{"id":"g35-s10","prompt":"When cousins or friends visit, your child...","options":[{"id":"g35-s10-a","domain":"storyteller","text":"entertains everyone with jokes and stories"},{"id":"g35-s10-b","domain":"connector","text":"makes sure no one is left out and plans the fun"},{"id":"g35-s10-c","domain":"cultivator","text":"takes them outside to explore the yard or the creek"}]},{"id":"g35-s11","prompt":"With a school project, your child...","options":[{"id":"g35-s11-a","domain":"organizer","text":"makes a plan, a list or a chart first"},{"id":"g35-s11-b","domain":"maker","text":"wants to build a model or do a demonstration"},{"id":"g35-s11-c","domain":"seeker","text":"wants to dig into the why behind it, and what it means"}]},{"id":"g35-s12","prompt":"Alone in their room, your child is most likely to...","options":[{"id":"g35-s12-a","domain":"designer","text":"draw, design, or build something detailed"},{"id":"g35-s12-b","domain":"psalmist","text":"play an instrument, sing, or make up music"},{"id":"g35-s12-c","domain":"ponderer","text":"journal, read, or simply think"}]}],"frequency":[{"id":"g35-f01","domain":"storyteller","text":"read, write, or tell stories for fun"},{"id":"g35-f02","domain":"organizer","text":"solve puzzles, work with numbers, or ask how things work"},{"id":"g35-f03","domain":"designer","text":"draw, map, or build things they picture in their head"},{"id":"g35-f04","domain":"maker","text":"build, fix, or make things with their hands"},{"id":"g35-f05","domain":"psalmist","text":"sing, play music, or notice sounds and rhythms"},{"id":"g35-f06","domain":"connector","text":"help others, or look for ways to do things together"},{"id":"g35-f07","domain":"ponderer","text":"want time alone to think things through"},{"id":"g35-f08","domain":"cultivator","text":"notice, collect, or ask about plants, animals or the outdoors"},{"id":"g35-f09","domain":"seeker","text":"ask big questions about God, life, or right and wrong"}]}$bank$::jsonb, true, '2026-11-18T12:00:00Z')
on conflict (version) do nothing;

insert into public.wired_question_banks (version, set_kind, bank, active, approved_at)
values ('g68-v1', 'g6_8', $bank${"version":"g68-v1","set_kind":"g6_8","approved_at":"2026-11-19","source":"Wired_Quiz_Grades6-8_Question_Set.md","weights":{"scenario":0.5,"frequency":0.5},"instructions":"Think about your child over the past month. For each moment, pick the ONE answer that sounds most like your child right now, even if more than one fits. There are no wrong answers: every choice is a strength.","frequency_stem":"In the past month, how often does your child...","scale":{"points":5,"labels":["Rarely","Sometimes","Often","Very often","Constantly"]},"scenarios":[{"id":"g68-s01","prompt":"A free afternoon with no plans. Your child is most likely to...","options":[{"id":"g68-s01-a","domain":"storyteller","text":"read, or write a story, a script or a comic"},{"id":"g68-s01-b","domain":"organizer","text":"work on a strategy game, a code, or a brain teaser"},{"id":"g68-s01-c","domain":"designer","text":"draw, design something, or rearrange their room"}]},{"id":"g68-s02","prompt":"In a co-op class or youth group, your child comes alive during...","options":[{"id":"g68-s02-a","domain":"maker","text":"anything hands-on: labs, building, sports or active games"},{"id":"g68-s02-b","domain":"psalmist","text":"worship, choir, or anything with music and rhythm"},{"id":"g68-s02-c","domain":"connector","text":"small-group time and getting to know everyone"}]},{"id":"g68-s03","prompt":"On a camping trip or a long day outdoors, your child...","options":[{"id":"g68-s03-a","domain":"ponderer","text":"wanders off a little way and enjoys the quiet"},{"id":"g68-s03-b","domain":"cultivator","text":"names the birds, plants or tracks, or wants to look them up"},{"id":"g68-s03-c","domain":"seeker","text":"asks big questions, like why God made the world the way He did"}]},{"id":"g68-s04","prompt":"When your child is upset about something, they usually...","options":[{"id":"g68-s04-a","domain":"storyteller","text":"talk it out, or write about it"},{"id":"g68-s04-b","domain":"maker","text":"do something physical: shoot hoops, build, or go for a run"},{"id":"g68-s04-c","domain":"ponderer","text":"go off alone and think it through"}]},{"id":"g68-s05","prompt":"On a long road trip, your child...","options":[{"id":"g68-s05-a","domain":"organizer","text":"tracks the route, the miles or the time left"},{"id":"g68-s05-b","domain":"psalmist","text":"has music on and knows every word"},{"id":"g68-s05-c","domain":"cultivator","text":"watches the land change and points out animals and farms"}]},{"id":"g68-s06","prompt":"At church, your child is most drawn to...","options":[{"id":"g68-s06-a","domain":"designer","text":"the art, the building, or sketching during the sermon"},{"id":"g68-s06-b","domain":"connector","text":"the people, from the little kids to the older folks"},{"id":"g68-s06-c","domain":"seeker","text":"the teaching, and asking hard questions about it afterward"}]},{"id":"g68-s07","prompt":"Late in the evening, your child is most likely to...","options":[{"id":"g68-s07-a","domain":"storyteller","text":"be deep in a book, or writing something of their own"},{"id":"g68-s07-b","domain":"psalmist","text":"be listening to music, playing, or making up songs"},{"id":"g68-s07-c","domain":"seeker","text":"want to talk about God, purpose, or what is fair and right"}]},{"id":"g68-s08","prompt":"On family game night, your child...","options":[{"id":"g68-s08-a","domain":"organizer","text":"figures out the best strategy and knows every rule"},{"id":"g68-s08-b","domain":"connector","text":"keeps everyone laughing and makes sure no one is left out"},{"id":"g68-s08-c","domain":"ponderer","text":"joins in, then wants time to themselves afterward"}]},{"id":"g68-s09","prompt":"Given a free Saturday and some supplies, your child would...","options":[{"id":"g68-s09-a","domain":"designer","text":"design something: a room layout, a sketchbook page, a model"},{"id":"g68-s09-b","domain":"maker","text":"build, repair or take apart something with real tools"},{"id":"g68-s09-c","domain":"cultivator","text":"work in the garden, train a pet, or explore the creek"}]},{"id":"g68-s10","prompt":"When friends come over, your child...","options":[{"id":"g68-s10-a","domain":"storyteller","text":"has everyone laughing at their stories and jokes"},{"id":"g68-s10-b","domain":"connector","text":"plans the fun and makes sure everyone feels welcome"},{"id":"g68-s10-c","domain":"cultivator","text":"heads outside with them: the woods, the barn or the backyard"}]},{"id":"g68-s11","prompt":"Handed a big project, your child...","options":[{"id":"g68-s11-a","domain":"organizer","text":"breaks it into steps, a list or a schedule first"},{"id":"g68-s11-b","domain":"maker","text":"jumps in to build, test or try something"},{"id":"g68-s11-c","domain":"seeker","text":"wants to know why it matters before they start"}]},{"id":"g68-s12","prompt":"On a quiet evening at home, your child is most likely to...","options":[{"id":"g68-s12-a","domain":"designer","text":"sketch, design, or work on something detailed"},{"id":"g68-s12-b","domain":"psalmist","text":"practice an instrument, sing, or make a playlist"},{"id":"g68-s12-c","domain":"ponderer","text":"journal, or sit and think things over"}]}],"frequency":[{"id":"g68-f01","domain":"storyteller","text":"read, write, or tell stories for fun"},{"id":"g68-f02","domain":"organizer","text":"enjoy puzzles, numbers, or figuring out how things work"},{"id":"g68-f03","domain":"designer","text":"draw, design, or picture how something will look before making it"},{"id":"g68-f04","domain":"maker","text":"build, fix, cook, or make things with their hands"},{"id":"g68-f05","domain":"psalmist","text":"sing, play music, or notice sounds and rhythms"},{"id":"g68-f06","domain":"connector","text":"help others, or bring people together"},{"id":"g68-f07","domain":"ponderer","text":"want time alone to think things through"},{"id":"g68-f08","domain":"cultivator","text":"notice, care for, or ask about plants, animals or the outdoors"},{"id":"g68-f09","domain":"seeker","text":"ask big questions about God, life, or right and wrong"}]}$bank$::jsonb, true, '2026-11-19T12:00:00Z')
on conflict (version) do nothing;

